// DeleteUniqueIndexCache 删除索引存在的缓存
func (h *HomeworkAssistantScoreRepo) DeleteIndexCache(ctx context.Context, data ...*devices_learn_model.HomeworkAssistantScore) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, h.cache.Key(CacheHomeworkAssistantScoreByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[h.cache.Key(CacheHomeworkAssistantScoreByIDPrefix, item.ID)] = struct{}{}
			KeyMap[h.cache.Key(CacheHomeworkAssistantScoreByUserIDScoreTypeDatePrefix, item.UserID, item.ScoreType, item.Date)] = struct{}{}
			KeyMap[h.cache.Key(CacheHomeworkAssistantScoreByUserIDScoreTypePrefix, item.UserID, item.ScoreType)] = struct{}{}
			KeyMap[h.cache.Key(CacheHomeworkAssistantScoreByUserIDPrefix, item.UserID)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := h.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
